#!/usr/bin/env bash
# PostToolUse hook: gofmt edited Go files; warn when a migration lacks its down pair.
set -euo pipefail
file=$(jq -r '.tool_input.file_path // empty')
[ -z "$file" ] && exit 0

case "$file" in
  */internal/db/*.go) ;; # generated by sqlc
  *.go) command -v gofmt >/dev/null && gofmt -w "$file" ;;
  */migrations/*.up.sql)
    down="${file%.up.sql}.down.sql"
    if [ ! -f "$down" ]; then
      echo "Migration $file has no matching .down.sql — create it (see .claude/rules/database.md)." >&2
      exit 2
    fi
    ;;
esac
exit 0
